export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly problem?: Problem | ValidationProblem,
  ) {
    super(problem?.title ?? `HTTP ${status}`);
    this.name = "ApiError";
  }

  // fieldErrors maps the validation problems of a 422 to field names.
  get fieldErrors(): { field: string; code: string; message: string }[] {
    const errs = (this.problem as ValidationProblem | undefined)?.errors;
    return errs ?? [];
  }
}

// The entity types come from the meta-model at runtime (api/openapi.yaml describes them as an
// open object), so their shape is spelled out here once.
export type Label = Record<string, string>;
export type FieldType =
  "text" | "number" | "boolean" | "date" | "datetime" | "choice" | "reference" | "sequence";
export type Field = {
  name: string;
  type: FieldType;
  label?: Label;
  description?: Label;
  required?: boolean;
  unique?: boolean;
  searchable?: boolean;
  max_length?: number;
  min?: number;
  max?: number;
  options?: { value: string; label?: Label }[];
  to?: string;
  // prefix comes before the running number of a sequence field (PL49): "INC-" shows INC-24817.
  prefix?: string;
  default?: unknown;
  // trait names the trait the field came from; computed fields (the sums of the trait costs,
  // PL20) are kept by the server and never sent.
  trait?: string;
  computed?: boolean;
  // translatable text fields keep a value per language (PL21); the form edits the German one.
  translatable?: boolean;
  // formula makes the field calculated by the server (PL22): shown, never sent.
  formula?: string;
  // format "rich" makes a text field formatted text (UI7): the editor, HTML the server cleans.
  // rich: formatted text (UI7); priority: a number shown as a mark P1 … (UI29).
  format?: "rich" | "priority";
  // snippets names the use of the text modules the editor offers (SD8), e.g. "solution".
  snippets?: string;
  // hidden is set by the customer layer (PL43): left out of forms and lists, kept by the API.
  hidden?: boolean;
  // rollup sums or counts the records of another type that point here (WF13).
  rollup?: { from: string; via: string; op: "sum" | "count"; field?: string; where?: string };
};
// category gives the colour of the state's mark (UI29): open, active, waiting or done.
export type State = {
  name: string;
  label?: Label;
  initial?: boolean;
  category?: "open" | "active" | "waiting" | "done";
};
// disabled is set by the customer layer (UI26.1): kept, but neither offered nor taken.
export type Transition = {
  name: string;
  label?: Label;
  from: string[];
  to: string;
  when?: string;
  // by names the roles that alone may take it; comment whether it takes a text (SD-Plan N8).
  by?: string[];
  comment?: "required" | "optional";
  disabled?: boolean;
};
// ActorRole is a role at the record (WF3): who may hold it.
export type ActorRole = { name: string; label?: Label; to: string[]; single?: boolean };
// ActorRef is one holder of a role.
export type ActorRef = { type: string; id: string };
// PortalRead is the reading area of a type in the portal (SD16a): its name in the head, the
// fields its page shows, and the reference field to a tree list it is browsed by.
// With facts the list shows these fields with each record as cards, sorted by sort (SD13).
export type PortalRead = {
  label: Label;
  fields: string[];
  group?: string;
  facts?: string[];
  sort?: string;
};
// OrderSpec makes the records orderable with the form a field names (SD13, SD-Plan N19).
export type OrderSpec = { form: string; copy?: Record<string, string>; relation?: string };
// Suggest says where the records of a type are suggested while others are written (SD18):
// for types or traits ("trait:sd.ticket"), searched with the fields from.
export type Suggest = {
  label: Label;
  for: string[];
  from: string[];
  relation?: string;
  apply?: { label: Label; set: Record<string, string> };
};
export type TypeDefinition = {
  name: string;
  package?: string;
  label?: Label;
  description?: Label;
  title_field?: string;
  fields: Field[];
  states?: State[];
  transitions?: Transition[];
  // traits name the building blocks the type pulls in (PL17): history, timeline (PL42), …
  traits?: string[];
  actors?: ActorRole[];
  // portal offers the type in the portal for users with the fields to create with (UI10), or
  // for reading in an area of its own in the head of the portal (SD16a).
  portal?: { fields?: string[]; read?: PortalRead };
  // revision is the hash of the effective definition, base and customer layer (PL43).
  revision?: string;
  // layout is where the workflow editor draws each state (UI26.2); set by the customer layer.
  layout?: Record<string, { x: number; y: number }>;
  // timed tells that SLA clocks run on the records: the list shows their deadline (UI34).
  timed?: boolean;
  // suggest offers the type's records while records of other types are written (SD18).
  suggest?: Suggest;
  // readers let persons read without a grant (SD16a), some also comment (SD18).
  readers?: { when?: string; roles?: string[]; actions?: string[] }[];
  // order makes the records orderable, offers of the catalog (SD13).
  order?: OrderSpec;
  // approval names the transitions after an approval (WF6) and the fields whose changes wait
  // for approval (hold, SD17).
  approval?: {
    requested?: string;
    approved?: string;
    rejected?: string;
    hold?: { fields: string[]; when?: string; approvers: string; message?: string };
  };
};
export type TransitionInfo = components["schemas"]["TransitionInfo"];
// FieldStates is what the field states of the type (WF2) say for a record or a new one.
export type FieldStates = components["schemas"]["FieldStates"];

const csrf: Middleware = {
  onRequest({ request }) {
    request.headers.set("X-Requested-With", "itsm");
    // Reading follows the language of the person (SD16c): lists, search, names and the portal
    // show the translation where there is one, else German. The form edits the German value
    // (PL21, E98; one version, SD-Plan E10): api.get reads German unless asked to read, and
    // writing stays German, so an English session never saves English into the German column.
    if (!request.headers.has("Accept-Language")) {
      request.headers.set("Accept-Language", i18n.language === "en" ? "en" : "de");
    }
    request.headers.set("Content-Language", "de");
    return request;
  },
};

export const client = createClient<paths>({
  // Relative in the browser; the tests run under Node, whose Request needs an absolute URL.
  baseUrl: typeof window === "undefined" ? "http://localhost" : window.location.origin,
  credentials: "same-origin",
  // Resolve fetch at call time, so that tests can replace it after the module loaded.
  fetch: (request) => globalThis.fetch(request),
});
client.use(csrf);

// unwrap turns the {data, error, response} of openapi-fetch into data or ApiError.
function unwrap<T>(result: { data?: T; error?: unknown; response: Response }): T {
  if (result.response.ok) {
    return result.data as T;
  }
  throw new ApiError(result.response.status, result.error as Problem | undefined);
}

